        self.parent = parent
        self.line = line
        self.fn = None
        self.original_fn = None
        self.before = None
        self.after = None
        self.symbols = []
        self.symbol_lines = []
        self.alias_line = line
        self.user_options = []

    def path(self):
        return (self.parent.path() if self.parent else []) + [self.name]

    def descend(self, name):
        for child in self.subcommands:
            if name == child.name or name in child.aliases:
                return child
        return None

    def inherited_meta(self, key, default=None):
        if key in self.meta:
            return self.meta[key]
        return self.parent.inherited_meta(key, default) if self.parent else default

    def has_meta(self, key):
        return key in self.meta or bool(self.parent and self.parent.has_meta(key))

    def default_command(self):
        for sub in self.subcommands:
            if 'default-subcommand' in sub.meta:
                return sub
        return None

    def export(self):
        def clean(p):
            return {k:v for k,v in p.items() if not k.startswith('_')}
        out = dict(name=self.name, describe=self.describe, version=self.version,
                   aliases=self.aliases, flag_options=[clean(p) for p in self.options],
                   positionals=[clean(p) for p in self.args], envs=[clean(p) for p in self.envs],
                   subcommands=[s.export() for s in self.subcommands])
        if self.before:
            out['before_hook'] = self.before
        if self.after:
            out['after_hook'] = self.after
        if 'combine-shorts' in self.meta:
            out['combine_shorts'] = True
        if 'inherit-flag-options' in self.meta:
            out['inherit_flag_options'] = True
        if 'dotenv' in self.meta:
            out['dotenv'] = self.meta['dotenv'] or '.env'
        if self.meta:
            out['metadata'] = self.meta.copy()
        out['command_fn'] = self.fn
        return out


def first_word(s):
    """A definition word may contain a quoted default or bracketed choices."""
    q = None
    depth = 0
    for i, char in enumerate(s):
        if q:
            if char == q:
                q = None
        elif char in "'\"`":
            q = char
        elif char == '[':
            depth += 1
        elif char == ']':
            depth = max(0, depth-1)
        elif char.isspace() and depth == 0:
            return s[:i], s[i:].lstrip()
    return s, ''


def parse_suffix(text, tag, line):
    is_opt = tag in ('flag', 'option')
    pattern = r'([-+]{1,2})([\w.:-]+)' if is_opt else r'([\w.:-]+)'
    m = re.match(pattern, text, re.ASCII)
    if not m:
        raise DefinitionError(f'syntax error at line {line}')
    raw = m.group(0)
    rest = text[len(raw):]
    prefix = False
    assigned = False
    if is_opt:
        if raw.endswith(':'):
            assigned = True
            raw = raw[:-1]
        if raw.endswith('-'):
            prefix = True
            raw = raw[:-1]
    if not raw.lstrip('-+'):
        raise DefinitionError(f'syntax error at line {line}')
    modifier = ''
    delim = None
    if rest and rest[0] in '!+*~':
        modifier, rest = rest[0], rest[1:]
        if modifier in '*+' and rest and rest[0] in ',:;|/':
            delim, rest = rest[0], rest[1:]
    default, choice = None, None
    if rest.startswith('='):
        val = rest[1:]
        if val.startswith('`') and val.endswith('`'):
            default = dict(type='Fn', value=val[1:-1])
        elif val.startswith(('"', "'")):
            if len(val)<2 or val[-1]!=val[0]:
                raise DefinitionError(f'syntax error at line {line}')
            default = dict(type='Value', value=val[1:-1])
        else:
            default = dict(type='Value', value=val)
        rest = ''
    elif rest.startswith('[') and rest.endswith(']'):
        vals = rest[1:-1]
        is_default = vals.startswith('=')
        if is_default:
            vals = vals[1:]
        if vals.startswith('`') and vals.endswith('`'):
            choice = dict(type='Fn', data=[vals[1:-1], True])
        elif vals.startswith('?`') and vals.endswith('`'):
            choice = dict(type='Fn', data=[vals[2:-1], False])
        else:
            items = vals.split('|')
            items = [v[1:-1] if len(v)>1 and v[0]==v[-1] and v[0] in "'\"" else v for v in items]
            choice = dict(type='Values', data=items)
            if is_default:
                default = dict(type='Value', value=items[0])
        rest = ''
    if rest or (tag == 'flag' and (modifier not in ('', '*') or default or choice or assigned or prefix or delim)):
        raise DefinitionError(f'syntax error at line {line}')
    return raw, modifier, delim, default, choice, prefix, assigned


def parse_param(text, tag, line):
    word, rem = first_word(text.strip())
    short = None
    if tag in ('option', 'flag') and re.fullmatch(r'[-+][\w]', word, re.ASCII):
        nxt, tail = first_word(rem)
        if re.match(r'[-+][\w-]', nxt, re.ASCII):
            short, word, rem = word, nxt, tail
    raw, mod, delim, default, choice, prefix, assigned = parse_suffix(word, tag, line)
    if tag in ('flag', 'option'):
        p = option_record(raw, short, flag=(tag=='flag'))
        p.update(required=mod in ('!', '+'), multiple_values=mod in ('*', '+', '~'),
                 multiple_occurs=mod in ('*', '+'), terminated=mod=='~',
                 prefixed=prefix, assigned=assigned, delimiter=delim,
                 default=default, choice=choice)
        if tag == 'option' and mod == '~':
            p['notations'][-1] += '~'
            p['num_args'] = [1,32767]
    else:
        p = dict(id=raw, describe='', notation=raw.upper(), required=mod in ('!', '+'),
                 multiple=mod in ('*', '+', '~'), delimiter=delim, terminated=mod=='~',
                 default=default, choice=choice, env=None)
    if tag != 'env':
        env = re.match(r'^\$(\$|[a-zA-Z_][a-zA-Z_0-9]*)(?:\s+|$)', rem)
        if env:
            p['env'] = variable_name(p['id']).upper() if env.group(1)=='$' else env.group(1)
            rem = rem[env.end():]
    if tag in ('option', 'arg'):
        notations = []
        while rem.startswith('<'):
            notation = re.match(r'<([^\s<>]+)>(?:\s+|$)', rem)
            if not notation:
                break
            notations.append(notation.group(1).upper())
            rem = rem[notation.end():]
            if tag=='arg':
                break
        if notations:
            if tag == 'arg':
                p['notation'] = notations[0]
            else:
                p['notations'] = notations
                mi = ma = len(notations)
                end = notations[-1][-1:]
                if end == '?':
                    mi -= 1
                elif end in ('*', '+', '~'):
                    ma=32767
                    if end=='*':
                        mi-=1
                    if end=='~':
                        p['terminated']=True
                p['num_args'] = [mi,ma]
                p['multiple_values'] |= ma>1
    p['describe'] = rem.rstrip()
    p['_line'] = line
    p['_tag'] = tag
    if tag=='env':
        if p['multiple'] or delim or p['terminated']:
            raise DefinitionError(f'@env(line {line}) is invalid, can only be a single value')
        if not re.fullmatch(r'[a-zA-Z_][a-zA-Z0-9_]*',p['id']):
            raise DefinitionError(f'@env(line {line}) is invalid, invalid name')
        p = {k:v for k,v in p.items() if k not in ['notation','multiple','delimiter','terminated','env']}
        p['inherited'] = False
    return p


class Definition:
    def __init__(self, path, source=None, name=None):
        self.path = path
        self.source = source
        self.functions = {}
        self.root = Command(name or script_name(path))
        self.commands = [self.root]
        if source is None:
            with open(path, encoding='utf-8') as f:
                self.source=f.read()
        self.parse()

    def parse(self):
        current = self.root
        pending = None
        sealed = False
        desc = None
        fn_commands = {}
        for n,line in enumerate(self.source.splitlines(),1):
            match = re.match(r'^\s*#\s+@(\S+)(?:\s+(.*))?$', line)
            if match:
                tag = match.group(1)
                text = (match.group(2) or '').strip()
                desc = None
                if tag not in ['describe','version','cmd','alias','arg','option','flag','env','meta']:
                    raise DefinitionError(f'@{tag}(line {n}) is unknown tag')
                if tag=='cmd':
                    if pending:
                        self.root.subcommands.append(pending)
                    current=Command(self.root.name,self.root,n)
                    self.commands.append(current)
                    current.describe = text
                    pending = current
                    sealed=False
                    desc=(current, 'describe')
                    continue
                if sealed:
                    raise DefinitionError(f'@{tag}(line {n}) shouldn\'t be here, @cmd is missing?')
                if tag in ('describe','version'):
                    setattr(current, tag, text)
                    if tag == 'describe':
                        desc=(current,'describe')
                elif tag=='alias':
                    current.aliases += [a for a in (text.split()[0] if text else '').split(',') if a]
                    current.alias_line=n
                elif tag=='meta':
                    word, value=first_word(text)
                    if not word:
                        raise DefinitionError(f'syntax error at line {n}')
                    current.meta[word]=value if value else None
                    if word=='version':
                        current.version=value if value else None
                    if word=='symbol':
                        current.symbol_lines.append((value,n))
                else:
                    p=parse_param(text,tag,n)
                    collection = current.options if tag in ('flag','option') else current.args if tag=='arg' else current.envs
                    for old in collection:
                        collision = None
                        if tag in ('flag','option'):
                            for name in [p['long_name'],p['short_name']]:
                                if name and name in [old['long_name'],old['short_name']]:
                                    collision=name
                                    break
                        elif old['id']==p['id']:
                            collision=p['id']
                        if collision:
                            raise DefinitionError(f"@{tag}(line {n}) has '{collision}' already exists at line {old['_line']}")
                    collection.append(p)
                    desc=(p,'describe')
                continue
            comment = re.match(r'^\s*#(?: ?)(.*)$',line)
            if comment:
                if desc:
                    obj,key=desc
                    if isinstance(obj,dict):
                        obj[key]+='\n'+comment.group(1).rstrip()
                    else:
                        setattr(obj,key,getattr(obj,key)+'\n'+comment.group(1).rstrip())
                continue
            desc=None
            # Functions are recognized by their declaration line, without interpreting their body.
            fm = re.match(r'^\s*(?:function\s+)?([\w.:+\-]+)\s*\(\s*\)\s*', line)
            if not fm:
                fm=re.match(r'^\s*function\s+([\w.:+\-]+)(?:\s|\{)',line)
            if fm:
                fn=fm.group(1)
                self.functions[fn]=n
                if pending:
                    parts=fn.split('::')
                    parent=self.root
                    if len(parts)>1:
                        parent=fn_commands.get('::'.join(parts[:-1]))
                        if not parent:
                            raise DefinitionError(f'{fn}(line {n}) lack of parent command')
                    current.parent=parent
                    current.name=parts[-1]
                    current.fn=current.original_fn=fn
                    current.line=n
                    auto_alias=current.name.replace('_','-')
                    if auto_alias!=current.name:
                        current.aliases.insert(0,auto_alias)
                    seen=[]
                    for a in current.aliases:
                        if a not in seen and a!=current.name:
                            seen.append(a)
                    current.aliases=seen
                    for other in parent.subcommands:
                        oldnames=[other.name]+other.aliases
                        if current.name in oldnames:
                            raise DefinitionError(f'{fn}(line {n}) conflicts with cmd or alias at line {other.line}')
                        if any(a in oldnames for a in current.aliases):
                            raise DefinitionError(f'@alias(line {current.alias_line}) conflicts with cmd or alias at line {other.line}')
                    parent.subcommands.append(current)
                    fn_commands[fn]=current
                    pending=None
                    sealed=True
        if pending:
            self.root.subcommands.append(pending)
        for cmd in self.commands:
            cmd.describe=cmd.describe.rstrip()
            for p in cmd.options+cmd.args+cmd.envs:
                p['describe']=p['describe'].rstrip()
                for info in [p.get('default'),p.get('choice')]:
                    if info and info['type']=='Fn':
                        fn=info.get('value',info.get('data',[None])[0])
                        if fn not in self.functions:
                            raise DefinitionError(f"{fn}(line {p['_line']}) is missing")
            if cmd is self.root:
                cmd.fn='main' if 'main' in self.functions else None
            elif cmd.subcommands:
                main=cmd.original_fn+'::main' if cmd.original_fn else ''
                cmd.fn=main if main in self.functions else None
            prefix='' if cmd is self.root else (cmd.original_fn or '')+'::'
            cmd.before=prefix+'_argc_before' if prefix+'_argc_before' in self.functions else None
            cmd.after=prefix+'_argc_after' if prefix+'_argc_after' in self.functions else None
            for value,ln in cmd.symbol_lines:
                m=re.fullmatch(r'([^\w\s])([\w-]+)(?:\[`([^`]+)`\])?',value)
                if not m:
                    raise DefinitionError(f'@meta(line {ln}) invalid symbol value')
                symbol,ident,fn=m.groups()
                if fn and fn not in self.functions:
                    raise DefinitionError(f'{fn}(line {ln}) is missing')
                cmd.symbols.append((symbol,ident,fn))
        self.finalize(self.root)

    def finalize(self,cmd):
        own=cmd.options[:]
        cmd.user_options=own[:]
        cmd.user_envs=cmd.envs[:]
        described=any(p['describe'] for p in own)
        used=set()
        for p in own:
            used.add(p['long_name'])
            used.add(p['short_name'])
        one_hyphen=any(not p['long_name'].startswith('--') for p in own)
        hyphen='-' if one_hyphen else '--'
        for ident,short in [('help','-h')]+([('version','-V')] if cmd is self.root or cmd.version else []):
            if not any(p['id']==ident for p in own):
                p=option_record(hyphen+ident,None if short in used else short,'Print '+ident if described else '')
                p['_auto']=True
                p['_line']=0
                p['_tag']='flag'
                cmd.options.append(p)
        if cmd.parent:
            if cmd.has_meta('inherit-flag-options'):
                inherited=[]
                for p in cmd.parent.options:
                    if p.get('_auto'):
                        continue
                    names=[p['long_name'],p['short_name']]
                    if any(v and v in used for v in names):
                        continue
                    p=copy.deepcopy(p)
                    p['inherited']=True
                    inherited.append(p)
                cmd.options=inherited+cmd.options
            env_ids={p['id'] for p in cmd.envs}
            inherited=[]
            for p in cmd.parent.envs:
                if p['id'] not in env_ids:
                    p=copy.deepcopy(p)
                    p['inherited']=True
                    inherited.append(p)
            cmd.envs=inherited+cmd.envs
        for sub in cmd.subcommands:
            self.finalize(sub)
