"""Text rendering shared by help, diagnostics and shell evaluation."""
import os
import re
import textwrap
import unicodedata


def quote(value):
    value=str(value)
    if not value or any(c.isspace() or c in "|&;<>($`\\\"'*?[#~=%%" for c in value):
        return "'" + value.replace("'", "'\\''") + "'"
    return value


def array(values):
    return '( ' + ' '.join(quote(x) for x in values) + ' )'


def arg_label(p):
    brackets=('<','>') if p['required'] else ('[',']')
    return brackets[0]+p['notation']+brackets[1]+('...' if p['multiple'] else '')


def option_value(p):
    if p['flag']:
        return '...' if p['multiple_occurs'] else ''
    if p['multiple_occurs'] and len(p['notations'])==1:
        value=('<'+p['notations'][0]+'>' if p['required'] else '['+p['notations'][0]+']')+'...'
    else:
        value=' '.join('<'+n+'>' for n in p['notations'])
    return ('=' if p['assigned'] else ' ')+value


def option_label(p):
    return p['long_name']+option_value(p)


def option_display(p):
    name=p['long_name']
    if p['short_name']:
        start=p['short_name']+', '+(' ' if not name.startswith('--') else '')+name
    elif len(name)==2:
        start=name
    else:
        start='    '+(' ' if not name.startswith('--') else '')+name
    return start+option_value(p)


def description(p, multiline=False):
    s=p['describe']
    if multiline and '\n' in s:
        return s
    suffix=[]
    if p.get('env'):
        suffix.append('[env: '+p['env']+']')
    ch=p.get('choice')
    if ch and ch['type']=='Values':
        suffix.append('[possible values: '+', '.join(ch['data'])+']')
    default=p.get('default')
    if default and default['type']=='Value':
        suffix.append('[default: '+quote(default['value'])+']')
    return ' '.join(([s] if s else [])+suffix)


def synopsis(cmd):
    opts=[p for p in cmd.options if not p.get('_auto')]
    bits=[]
    if any(not p['required'] for p in opts):
        bits.append('[OPTIONS]')
    bits.extend(option_label(p) for p in opts if p['required'])
    if cmd.subcommands:
        bits.append('<COMMAND>')
    else:
        bits.extend(arg_label(p) for p in cmd.args)
    return ' '.join(cmd.path()+bits)


def width(s):
    return sum(0 if unicodedata.combining(c) else 2 if unicodedata.east_asian_width(c) in 'WF' else 1 for c in s)


def term_width():
    try:
        value=int(os.environ.get('TERM_WIDTH','0'))
        return max(20,value) if value else 100000
    except ValueError:
        return 100000


def wrap(s, limit, initial='', subsequent=''):
    if limit>=100000:
        return initial+s
    return textwrap.fill(s,width=max(1,limit),initial_indent=initial,
                         subsequent_indent=subsequent,expand_tabs=False,
                         replace_whitespace=False,break_long_words=False,
                         break_on_hyphens=False)


