"""Small roff renderer for command trees."""
from render import arg_label


def esc(s):
    return s.replace('\\', '\\e').replace('-', '\\-')


def italic(s):
    return '\\fI'+esc(s)+'\\fR'


def bold(s):
    return '\\fB'+esc(s)+'\\fR'


def default(p):
    d=p.get('default')
    return ' [default: '+esc(d['value'])+']' if d and d['type']=='Value' else ''


def describe(p):
    s=p['describe']
    out='\n'.join('.br\n'+esc(line) for line in s.split('\n')) if s else ''
    c=p.get('choice')
    if c and c['type']=='Values':
        if s:
            out+='\n.br\n'
        out+='\n.br\n[\\fIpossible values: \\fR'+', '.join(esc(v) for v in c['data'])+']'
    return out+'\n'


def manpage(cmd):
    name='-'.join(cmd.path())
    version=cmd.version or '0.0.0'
    out='.TH '+name.upper()+' 1  "'+name+' '+version+'" \n.SH NAME\n'+esc(name)
    if cmd.describe:
        out+=' \\- '+esc(cmd.describe.split('\n')[0])
    out+='\n.SH SYNOPSIS\n'+bold(' '.join(cmd.path()))
    if any(not p.get('_auto') for p in cmd.options):
        out+=' [OPTIONS]'
    if cmd.subcommands:
        out+=' <COMMAND>'
    elif cmd.args:
        out+=' '+' '.join(esc(arg_label(p)) for p in cmd.args)
    out+='\n'
    if '\n' in cmd.describe:
        out+='.SH DESCRIPTION\n'+'\n'.join('.br\n'+esc(line) for line in cmd.describe.split('\n'))+'\n'
    if cmd.args or any(not p.get('_auto') for p in cmd.options):
        out+='.SH OPTIONS\n'
        for p in cmd.options:
            out+='.TP\n'
            if p['short_name']:
                out+=bold(p['short_name'])+', '
            out+=bold(p['long_name'])
            if not p['flag']:
                ns=p['notations']
                if len(ns)>1:
                    out+=' '+' '.join(italic(n) for n in ns)
                else:
                    v=italic(ns[0])
                    if p['required']:
                        v='<'+v+'>'
                    elif p['multiple_occurs']:
                        v='['+v+']'
                    if p['multiple_occurs']:
                        v+='...'
                    out+='='+v
            out+=default(p)+'\n'+describe(p)
        for p in cmd.args:
            n=italic(p['notation'])
            n='<'+n+'>' if p['required'] else '['+n+']'
            if p['multiple']:
                n+='...'
            out+='.TP\n'+n+default(p)+'\n'+describe(p)
    if cmd.subcommands:
        out+='.SH SUBCOMMANDS\n'
        for sub in cmd.subcommands:
            out+='.TP\n'+esc('-'.join(sub.path()))+'(1)\n'
            if sub.describe:
                out+=esc(sub.describe)+'\n'
    if cmd.envs:
        out+='.SH "ENVIRONMENT VARIABLES:"\n'
        for p in cmd.envs:
            out+='.TP\n'+italic(p['id'])+('*' if p['required'] else '')+default(p)+'\n'+describe(p)
    if cmd.version:
        out+='.SH VERSION\n'+esc(cmd.version)+'\n'
    return out
