SHELLS=['bash','elvish','fish','nushell','powershell','xonsh','zsh','tcsh']

@dataclass
class Candidate:
    value: str
    description: str=''
    color: str='default'
    nospace: bool=False
    prefix: str=''
    display: str=None

    def __post_init__(self):
        if self.display is None:
            self.display=self.value


def parse_candidates(text):
    result=[]
    for line in text.splitlines():
        parts=line.split('\t')
        v=parts[0]
        if not v:
            continue
        nospace=v.endswith('\0')
        v=v.rstrip('\0')
        color='default'
        desc=''
        for part in parts[1:]:
            if part.startswith('/color:'):
                color=part[7:]
            elif not part.startswith('/'):
                desc=part
                break
        result.append(Candidate(v,desc,color,nospace))
    return result


def fn_candidates(definition,fn,words,variables=''):
    env=os.environ.copy()
    env['ARGC_COMPGEN']='1'
    return parse_candidates(run_function(definition,fn,words,variables,env))


