    cmd=definition.root
    previous=words[1:-1]
    current=words[-1]
    used=set()
    positional=[]
    waiting=None
    value_index=0
    ended=False
    vals={}
    def find(c,n):
        for p in c.options:
            if n in [p['long_name'],p['short_name']]:
                return p
            if p.get('_auto') and n=='--'+p['id']:
                return p
        return None
    i=0
    while i<len(previous):
        w=previous[i]
        if waiting:
            if waiting['terminated'] or not (len(w)>1 and w[0] in '-+'):
                vals.setdefault(waiting['id'],[]).append(w)
                value_index+=1
                if value_index>=waiting['num_args'][1]:
                    waiting=None;value_index=0
                i+=1;continue
            waiting=None;value_index=0
        if ended:
            positional.append(w);i+=1;continue
        if w=='--':
            ended=True;i+=1;continue
        if w=='help' and not positional:
            i+=1;continue
        child=cmd.descend(w) if not positional else None
        if child:
            cmd=child;positional=[];i+=1;continue
        p=find(cmd,w.split('=',1)[0])
        if p:
            used.add(p['id'])
