        items=[Candidate(v) for v in SHELLS if v.startswith(word)]
    elif word.startswith('--argc-') or word=='-':
        items=[Candidate('--argc-'+n,d,'cyan,bold' if takes_value else 'cyan') for n,d,takes_value in BUILTINS if ('--argc-'+n).startswith(word)]
    elif len(words)>2 and words[-2] in ('--argc-eval','--argc-run','--argc-build','--argc-mangen','--argc-export','--argc-parallel'):
        items=[Candidate('__argc_value=FILE')]
    else:
        script=find_script()
