def parallel_command(args):
    if len(args)<2:
        raise CLIError('Usage: argc --argc-parallel <SCRIPT> <ARGS>...')
    script=args[0]
    groups=[]
    group=[]
    for arg in args[1:]:
        if arg==':::':
            if group:
                groups.append(group);group=[]
        else:
            group.append(arg)
