        return 0
    def run(group):
        return run_script(script,['___parallel___']+group,False,True)
    failed=False
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(len(groups),32)) as executor:
        results=list(executor.map(run,groups))
    for p in results:
        sys.stdout.buffer.write(p.stdout)
        sys.stderr.buffer.write(p.stderr)
        failed|=p.returncode!=0
    return 1 if failed else 0


