        sys.stderr.buffer.write(p.stderr)
        failed|=p.returncode!=0
    return 1 if failed else 0


def main(args):
    try:
        flag=args[0] if args else ''
        rest=args[1:]
        if flag=='--argc-help':
            sys.stdout.write(HELP)
        elif flag=='--argc-version':
            print('argc 1.23.0')
        elif flag=='--argc-eval':
            sys.stdout.write(eval_command(rest))
        elif flag=='--argc-export':
            if not rest:
                raise CLIError('No script file provided')
            d=load_definition(rest[0])
            print(json.dumps(d.root.export(),ensure_ascii=False,indent=2))
        elif flag=='--argc-completions':
            if not rest:
                raise CLIError('Usage: argc --argc-completions <SHELL> [CMDS]...')
            if rest[0] not in SHELLS:
                raise CLIError('The provided shell is either invalid or missing, must be one of '+','.join(SHELLS))
            sys.stdout.write(completions(rest[0],rest[1:]))
        elif flag=='--argc-compgen':
            sys.stdout.write(complete_command(rest))
        elif flag=='--argc-mangen':
            if not rest:
                raise CLIError('No script file provided')
            if len(rest)<2:
                raise CLIError('No output dir')
            generate_man(load_definition(rest[0]),rest[1])
        elif flag=='--argc-build':
            if not rest:
                raise CLIError('No script file provided')
            from standalone import build
            d=load_definition(rest[0])
            text=build(d)
            if len(rest)<2:
                sys.stdout.write(text)
            else:
                path=rest[1]
                if path.endswith('/') or os.path.isdir(path):
                    path=os.path.join(path,os.path.basename(rest[0]))
                if os.path.dirname(path):
                    os.makedirs(os.path.dirname(path),exist_ok=True)
                with open(path,'w') as f:
                    f.write(text)
                os.chmod(path,0o755)
        elif flag=='--argc-create':
            create_script(rest)
        elif flag=='--argc-shell-path':
            print(shell_path())
        elif flag=='--argc-script-path':
            path=find_script()
            if not path:
                raise CLIError('Argcfile not found.')
            print(path)
        elif flag=='--argc-run':
            if not rest:
                raise CLIError('No script file provided')
            return run_script(rest[0],rest[1:]).returncode
        elif flag=='--argc-parallel':
            return parallel_command(rest)
        elif flag.startswith('--argc-'):
            raise CLIError('Unknown option `'+flag+'`')
        else:
            path=find_script()
            if not path:
                raise CLIError('Argcfile not found, try `argc --argc-help` for help.')
            return run_script(path,args).returncode
        return 0
    except CLIError as error:
        print(str(error),file=sys.stderr)
        return 1
    except OSError as error:
        print(os.strerror(error.errno)+f' (os error {error.errno})',file=sys.stderr)
        return 1

if __name__=='__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
